export const venueDefinitions = {
  bar: { en: "Bars", ru: "Бары", category: "bars", order: 1,
    googleTypes: ["bar", "pub", "beer_garden", "sports_bar"],
    description: "bars and pubs" },
  club: { en: "Clubs", ru: "Клубы", category: "bars", order: 2,
