  cocktail: { en: "Cocktail bars", ru: "Коктейльные бары", category: "bars", order: 4,
    googleTypes: ["cocktail_bar", "speakeasy"], description: "cocktail bars and speakeasies" },
  cafe: { en: "Cafes & coffee shops", ru: "Кафе и кофейни", category: "coffee", order: 5,
    googleTypes: ["cafe", "coffee_shop", "tea_house", "cat_cafe", "dog_cafe"],
    description: "cafes and coffee shops" },
  restaurant: { en: "Restaurants", ru: "Рестораны", category: "coffee", order: 0,
    googleTypes: ["restaurant", "steak_house", "food_court", "meal_takeaway", "meal_delivery"],
    description: "restaurants" },
  bakery: { en: "Bakeries", ru: "Пекарни", category: "coffee", order: 6,
    googleTypes: ["bakery"], description: "bakeries" },
  park: { en: "Parks", ru: "Парки", category: "nature", order: 7,
    googleTypes: ["park"], description: "public city parks for walking and relaxing outdoors" },
  garden: { en: "Gardens", ru: "Сады", category: "nature", order: 8,
    googleTypes: ["garden", "botanical_garden"], description: "gardens and botanical gardens" },
} as const satisfies Record<string, { en: string; ru: string; category: Category; order: number; googleTypes: readonly string[]; description: string }>;
export type VenueType = keyof typeof venueDefinitions;
export const venueTypes = Object.keys(venueDefinitions) as VenueType[];
export const venueTypeLabels = venueDefinitions;
export const discoveryVenueTypes = [...venueTypes].sort((a, b) => venueDefinitions[a].order - venueDefinitions[b].order);

/**
 * Types offered in this release, from ENABLED_VENUE_TYPES on the server or the
 * public setting `enabledVenueTypes` on the client ("restaurant,bar,club,wine,cocktail").
 * Unset means every type. Other types stay valid for saved places.
 */
export function enabledVenueTypes(list?: string | readonly string[] | null): VenueType[] {
  const raw = Array.isArray(list) ? list : typeof list === 'string' ? list.split(',') : [];
  const chosen = raw.map(item => item.trim()).filter((item): item is VenueType => (venueTypes as string[]).includes(item));
  return chosen.length ? chosen : [...venueTypes];
}
export const venueTypeScope = venueTypes.map(type => `${type}: ${venueDefinitions[type].description}`).join('; ');
type TypedPlace = { primaryType?: string | null; types?: readonly string[] };

function typeOf(value: string): VenueType | undefined {
  if (value.endsWith("_restaurant")) return "restaurant";
  return venueTypes.find(type => (venueDefinitions[type].googleTypes as readonly string[]).includes(value));
}

/** A restaurant serving drinks is still a restaurant, not a bar reference.
 * Older/provider records without a primary type use their specific Google types.
 * Generic `food`, `establishment`, names and taste tags never expand the scope. */
export function venueTypeOf(place: TypedPlace): VenueType | undefined {
  if (place.primaryType) return typeOf(place.primaryType);
  const types = (place.types ?? []).map(typeOf);
  const existing = (["club", "cocktail", "wine", "bar", "cafe", "bakery", "restaurant"] as const).find(type => types.includes(type));
  if (existing) return existing;
  // These broader outdoor places remain outside the initial city-parks scope,
  // even when legacy records also contain the generic park type.
  if (place.types?.some(type => ["national_park", "hiking_area", "beach", "amusement_park", "rv_park", "campground"].includes(type))) return undefined;
  return (["garden", "park"] as const).find(
    (type) => types.includes(type),
  );
}

export function venueCategory(type: VenueType): Category {
  return venueDefinitions[type].category;
}

export function referenceVenueTypes(
  places: readonly TypedPlace[],
  category?: Category,
): VenueType[] {
  const present = new Set(places.map(venueTypeOf));
  return venueTypes.filter(
    (type) =>
      present.has(type) && (!category || venueCategory(type) === category),
  );
}

export function matchesVenueTypes(
  place: TypedPlace,
  allowed: readonly VenueType[],
): boolean {
  const type = venueTypeOf(place);
  return type !== undefined && allowed.includes(type);
}
