export const cancelTrip = defineOperation<{ tripId: string }, void>(
  'trips.cancel',
  async (ctx, { tripId }) => {
    if (typeof tripId !== 'string' || tripId.length < 1 || tripId.length > 128) throw new Error('INVALID_TRIP_ID');
    const trip = await TripsCollection.findOneAsync({ _id: tripId, userId: ctx.userId });
    if (!trip || trip.status !== 'pending') return;

    await cancelTasks(`${TRIP_TASK}:${tripId}`);
    await TripsCollection.updateAsync(tripId, { $set: { status: 'cancelled' } });
    await settleTrip(tripId, ctx.userId, []);
  },
);

